import{_ as s,c as a,b as e,o as p}from"./app-DGgJ1dhj.js";const t={};function l(i,n){return p(),a("div",null,[...n[0]||(n[0]=[e(`<p>这三个核心文件构成了一条完整链路：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">编辑结构</span>
<span class="line">anatomy-tree.ts</span>
<span class="line">    ↓ AnatomyDraftInput</span>
<span class="line">发布前校验</span>
<span class="line">validate-anatomy-for-publish.ts</span>
<span class="line">    ↓ 合法定义</span>
<span class="line">检查真实文件树</span>
<span class="line">check-anatomy.ts</span>
<span class="line">    ↓ Result&lt;检查结果, 定义错误&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>index.ts</code> 只是桶导出，不包含业务逻辑。</p><h2 id="一、共同的数据结构" tabindex="-1"><a class="header-anchor" href="#一、共同的数据结构"><span>一、共同的数据结构</span></a></h2><p>核心类型定义在 <a href="G:/Save/Grogramming/CodeForge/daedalus/packages/schemas/src/anatomy-schema.ts:25">anatomy-schema.ts</a>。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">AnatomyStructure</span>
<span class="line">└── root</span>
<span class="line">    └── children: AnatomyNode[]</span>
<span class="line">        ├── FileEntry</span>
<span class="line">        ├── DirectoryEntry</span>
<span class="line">        │   └── children: AnatomyNode[]</span>
<span class="line">        └── OneOfGroup</span>
<span class="line">            └── alternatives: AnatomyEntry[]</span>
<span class="line">                ├── FileEntry</span>
<span class="line">                └── DirectoryEntry</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键类型可以简化为：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">AnatomyNode</span> <span class="token operator">=</span></span>
<span class="line">  <span class="token operator">|</span> AnatomyEntry</span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">      id<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">      kind<span class="token operator">:</span> <span class="token string">&quot;one_of&quot;</span><span class="token punctuation">;</span></span>
<span class="line">      minimumMatches<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span></span>
<span class="line">      maximumMatches<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span></span>
<span class="line">      alternatives<span class="token operator">:</span> AnatomyEntry<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> <span class="token class-name">AnatomyEntry</span> <span class="token operator">=</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">      kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span><span class="token punctuation">;</span></span>
<span class="line">      id<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">      name<span class="token operator">:</span> AnatomyName<span class="token punctuation">;</span></span>
<span class="line">      quantity<span class="token operator">:</span> AnatomyQuantity<span class="token punctuation">;</span></span>
<span class="line">      policyOverrides<span class="token operator">:</span> AnatomyPolicyOverrides<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">      kind<span class="token operator">:</span> <span class="token string">&quot;directory&quot;</span><span class="token punctuation">;</span></span>
<span class="line">      id<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">      name<span class="token operator">:</span> AnatomyName<span class="token punctuation">;</span></span>
<span class="line">      quantity<span class="token operator">:</span> AnatomyQuantity<span class="token punctuation">;</span></span>
<span class="line">      policyOverrides<span class="token operator">:</span> AnatomyPolicyOverrides<span class="token punctuation">;</span></span>
<span class="line">      children<span class="token operator">:</span> AnatomyNode<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里最重要的是：</p><ul><li><code>AnatomyNode</code> 可以是文件、目录或 <code>one_of</code>。</li><li><code>directory.children</code> 是 <code>AnatomyNode[]</code>，所以目录中可以放 <code>one_of</code>。</li><li><code>one_of.alternatives</code> 是 <code>AnatomyEntry[]</code>，不能直接嵌套另一个 <code>one_of</code>。</li><li>根节点不是普通目录，没有 <code>id</code>、<code>kind</code>、<code>name</code>，只有 <code>children</code>。</li><li><code>kind</code> 是判别字段。写出 <code>node.kind === &quot;directory&quot;</code> 后，TypeScript 就知道它一定存在 <code>children</code>。</li></ul><p>名称也采用判别联合：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">AnatomyName</span> <span class="token operator">=</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span> type<span class="token operator">:</span> <span class="token string">&quot;literal&quot;</span><span class="token punctuation">;</span> value<span class="token operator">:</span> <span class="token string">&quot;index.ts&quot;</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span> type<span class="token operator">:</span> <span class="token string">&quot;placeholder&quot;</span><span class="token punctuation">;</span> value<span class="token operator">:</span> <span class="token string">&quot;&lt;Name&gt;.tsx&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>数量规则：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token string">&quot;optional&quot;</span>      <span class="token comment">// 0..1</span></span>
<span class="line"><span class="token string">&quot;exactly_one&quot;</span>   <span class="token comment">// 1..1</span></span>
<span class="line"><span class="token string">&quot;one_or_more&quot;</span>   <span class="token comment">// 1..Infinity</span></span>
<span class="line"><span class="token string">&quot;zero_or_more&quot;</span>  <span class="token comment">// 0..Infinity</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h1 id="二、anatomy-tree-ts-树的构造、查询和修改" tabindex="-1"><a class="header-anchor" href="#二、anatomy-tree-ts-树的构造、查询和修改"><span>二、<code>anatomy-tree.ts</code>：树的构造、查询和修改</span></a></h1><p>文件：<a href="G:/Save/Grogramming/CodeForge/daedalus/packages/anatomies/src/core/anatomy-tree.ts:1">anatomy-tree.ts</a></p><p>它只关心“如何编辑定义树”，不判断真实文件是否符合定义。</p><h2 id="_1-uid-iife-闭包" tabindex="-1"><a class="header-anchor" href="#_1-uid-iife-闭包"><span>1. <code>uid</code>：IIFE + 闭包</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> uid <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> state <span class="token operator">=</span> <span class="token punctuation">{</span> counter<span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    state<span class="token punctuation">.</span>counter <span class="token operator">+=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> crypto<span class="token punctuation">.</span>randomUUID<span class="token operator">?.</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">??</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">node-</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>state<span class="token punctuation">.</span>counter<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">-</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是立即执行函数 IIFE。</p><p>执行过程：</p><ol><li>模块加载时执行外层 <code>() =&amp;gt; {...}</code>。</li><li>创建私有的 <code>state</code>。</li><li>返回真正的 <code>uid</code> 函数。</li><li>后续每次调用 <code>uid()</code>，都能访问同一个 <code>state</code>。</li></ol><p>需要注意：</p><ul><li><code>state</code> 对模块外部不可见。</li><li>主路径 <code>crypto.randomUUID()</code> 会生成合法 UUID。</li><li>fallback 的 <code>node-1-...</code> 不是 UUID，而 Zod Schema 要求 <code>z.string().uuid()</code>。现代浏览器和 Node 通常都有 <code>randomUUID</code>，但 fallback 与 Schema 约束并不完全一致。</li></ul><h2 id="_2-cloneentry-保留具体泛型类型" tabindex="-1"><a class="header-anchor" href="#_2-cloneentry-保留具体泛型类型"><span>2. <code>cloneEntry</code>：保留具体泛型类型</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> <span class="token function-variable function">cloneEntry</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token operator">&lt;</span><span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name">AnatomyEntry</span><span class="token operator">&gt;</span><span class="token punctuation">(</span>entry<span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token constant">T</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span><span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>entry<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token constant">T</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>T extends AnatomyEntry</code> 表示：</p><ul><li>参数必须属于 <code>AnatomyEntry</code>。</li><li>返回值保留传入时的具体类型。</li></ul><p>例如：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> directory <span class="token operator">=</span> <span class="token function">createDirectoryEntry</span><span class="token punctuation">(</span><span class="token string">&quot;src&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> cloned <span class="token operator">=</span> <span class="token function">cloneEntry</span><span class="token punctuation">(</span>directory<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// cloned 仍然知道自己是 directory，而不是宽泛的 AnatomyEntry</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>需要注意：</p><ul><li><code>JSON.parse()</code> 返回 <code>any</code>，所以这里必须用 <code>as T</code> 告诉 TS 返回类型。</li><li>这个断言由开发者承担正确性，TS 无法验证。</li><li>当前 Anatomy 数据只有普通对象、数组、字符串和数字，JSON 深拷贝基本可用。</li><li>如果以后加入 <code>Date</code>、<code>Map</code>、<code>undefined</code> 或自定义类，JSON 深拷贝会丢失信息。</li></ul><h2 id="_3-创建文件和目录" tabindex="-1"><a class="header-anchor" href="#_3-创建文件和目录"><span>3. 创建文件和目录</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">createFileEntry</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span></span>
<span class="line">  name<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span></span>
<span class="line">  quantity<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> AnatomyQuantityValues<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token builtin">number</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token operator">:</span> AnatomyEntry <span class="token operator">&amp;</span> <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>(typeof AnatomyQuantityValues)[number]</code> 是一个重要写法。</p><p>假设：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> AnatomyQuantityValues <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line">  <span class="token string">&quot;optional&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token string">&quot;exactly_one&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token string">&quot;one_or_more&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token string">&quot;zero_or_more&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>那么：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">typeof</span> AnatomyQuantityValues</span>
<span class="line"><span class="token comment">// readonly [&quot;optional&quot;, &quot;exactly_one&quot;, ...]</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token keyword">typeof</span> AnatomyQuantityValues<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token builtin">number</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token comment">// &quot;optional&quot; | &quot;exactly_one&quot; | &quot;one_or_more&quot; | &quot;zero_or_more&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它避免手写重复的联合类型。</p><p>返回类型：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">AnatomyEntry <span class="token operator">&amp;</span> <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>意思是返回值既是 AnatomyEntry，又确定为文件分支。因此调用方不会误访问目录的 <code>children</code>。</p><p>两个 Factory 默认：</p><ul><li>数量是 <code>&quot;optional&quot;</code>。</li><li>策略覆盖是空对象。</li><li>名称类型是 <code>&quot;literal&quot;</code>。</li><li>目录可以通过默认参数 <code>children = []</code> 创建空目录。</li></ul><h2 id="_4-locatenodeintree-递归查找" tabindex="-1"><a class="header-anchor" href="#_4-locatenodeintree-递归查找"><span>4. <code>locateNodeInTree</code>：递归查找</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">LocatedNode</span> <span class="token operator">=</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">      found<span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">      node<span class="token operator">:</span> AnatomyNode<span class="token punctuation">;</span></span>
<span class="line">      parent<span class="token operator">:</span> TreeNodeParent<span class="token punctuation">;</span></span>
<span class="line">      index<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span> found<span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是典型的可辨别联合：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token function">locateNodeInTree</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>result<span class="token punctuation">.</span>found<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  result<span class="token punctuation">.</span>node<span class="token punctuation">;</span>   <span class="token comment">// 安全</span></span>
<span class="line">  result<span class="token punctuation">.</span>parent<span class="token punctuation">;</span> <span class="token comment">// 安全</span></span>
<span class="line">  result<span class="token punctuation">.</span>index<span class="token punctuation">;</span>  <span class="token comment">// 安全</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>查找逻辑：</p><ol><li>遍历当前 <code>children</code>。</li><li>当前节点 ID 相等，立即返回。</li><li>当前节点是目录，递归检查 <code>child.children</code>。</li><li>当前节点是 <code>one_of</code>，先检查 alternatives 本身。</li><li>alternative 是目录时，再检查它的 children。</li><li>全部找不到返回 <code>{ found: false }</code>。</li></ol><p><code>parent</code> 有三种可能：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">TreeNodeParent</span> <span class="token operator">=</span></span>
<span class="line">  <span class="token operator">|</span> DirectoryEntry</span>
<span class="line">  <span class="token operator">|</span> OneOfGroup</span>
<span class="line">  <span class="token operator">|</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>index</code> 的含义取决于 <code>parent</code>：</p><ul><li><code>parent === null</code>：在 <code>root.children</code> 中的位置。</li><li><code>parent.kind === &quot;directory&quot;</code>：在 <code>parent.children</code> 中的位置。</li><li><code>parent.kind === &quot;one_of&quot;</code>：在 <code>parent.alternatives</code> 中的位置。</li></ul><p>这里的 <code>Extract</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">Extract<span class="token operator">&lt;</span>AnatomyNode<span class="token punctuation">,</span> <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;one_of&quot;</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>表示从 <code>AnatomyNode</code> 联合类型中提取 <code>kind: &quot;one_of&quot;</code> 的那个成员。</p><h2 id="_5-不可变修改" tabindex="-1"><a class="header-anchor" href="#_5-不可变修改"><span>5. 不可变修改</span></a></h2><h3 id="插入-insertanatomynode" tabindex="-1"><a class="header-anchor" href="#插入-insertanatomynode"><span>插入 <code>insertAnatomyNode</code></span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">insertAnatomyNode</span><span class="token punctuation">(</span>structure<span class="token punctuation">,</span> parentId<span class="token punctuation">,</span> node<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>parentId === null</code>：插入根节点。</li><li>找不到 parent：原样返回 <code>root</code>。</li><li>parent 不是目录：原样返回。</li><li>parent 是目录：复制目录、追加 child，再替换回树中。</li></ul><p>核心不可变写法：</p><p>root与root不是一个东西</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token operator">...</span>root<span class="token punctuation">,</span></span>
<span class="line">  root<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token operator">...</span>root<span class="token punctuation">.</span>root<span class="token punctuation">,</span></span>
<span class="line">    children<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token operator">...</span>root<span class="token punctuation">.</span>root<span class="token punctuation">.</span>children<span class="token punctuation">,</span> node<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>它不会对原来的 <code>children.push()</code>。</p><h3 id="删除-removeanatomynode" tabindex="-1"><a class="header-anchor" href="#删除-removeanatomynode"><span>删除 <code>removeAnatomyNode</code></span></a></h3><p>根据 parent 类型分别处理：</p><ul><li>根节点：过滤 <code>root.children</code>。</li><li><code>one_of</code> alternative：过滤 <code>alternatives</code>。</li><li>普通目录子节点：过滤 <code>children</code>。</li></ul><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">children<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token punctuation">(</span>child<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> child<span class="token punctuation">.</span>id <span class="token operator">!==</span> nodeId<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>注意：从二选一分组中删除一个 alternative 后，可能只剩一个选项。TypeScript 的 <code>AnatomyEntry[]</code> 无法表达“至少两个元素”，所以树编辑函数允许暂时产生不满足 Zod <code>.min(2)</code> 的草稿。</p><h3 id="更新-updateanatomynode" tabindex="-1"><a class="header-anchor" href="#更新-updateanatomynode"><span>更新 <code>updateAnatomyNode</code></span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">updateAnatomyNode</span><span class="token punctuation">(</span>root<span class="token punctuation">,</span> nodeId<span class="token punctuation">,</span> updater<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>updater</code> 使用高阶函数：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">(</span>node<span class="token operator">:</span> AnatomyNode<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> AnatomyNode</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>调用示例：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">updateAnatomyNode</span><span class="token punctuation">(</span>structure<span class="token punctuation">,</span> nodeId<span class="token punctuation">,</span> <span class="token punctuation">(</span>node<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token operator">...</span>node<span class="token punctuation">,</span></span>
<span class="line">  name<span class="token operator">:</span> <span class="token punctuation">{</span> type<span class="token operator">:</span> <span class="token string">&quot;literal&quot;</span><span class="token punctuation">,</span> value<span class="token operator">:</span> <span class="token string">&quot;new-name.ts&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>递归中通过 <code>map</code> 生成新数组：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">children<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>child<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>child<span class="token punctuation">.</span>id <span class="token operator">===</span> nodeId<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">updater</span><span class="token punctuation">(</span>child<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>child<span class="token punctuation">.</span>kind <span class="token operator">===</span> <span class="token string">&quot;directory&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token operator">...</span>child<span class="token punctuation">,</span> children<span class="token operator">:</span> <span class="token function">recurse</span><span class="token punctuation">(</span>child<span class="token punctuation">.</span>children<span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">return</span> child<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对 <code>one_of.alternatives</code> 有额外限制：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> updated <span class="token operator">=</span> <span class="token function">updater</span><span class="token punctuation">(</span>alt <span class="token keyword">as</span> AnatomyNode<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">return</span> updated<span class="token punctuation">.</span>kind <span class="token operator">===</span> <span class="token string">&quot;one_of&quot;</span></span>
<span class="line">  <span class="token operator">?</span> alt</span>
<span class="line">  <span class="token operator">:</span> <span class="token punctuation">(</span>updated <span class="token keyword">as</span> AnatomyEntry<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原因是 <code>alternatives</code> 只能包含文件或目录，不能把 alternative 更新为 <code>one_of</code>。</p><p>这里两个 <code>as</code> 都是类型逃生口。运行时通过 <code>kind</code> 检查保障数据约束，但 TS 本身没有从 updater 返回类型中得到这个保证。</p><p>另外，<code>updater</code> 应当写成纯函数。类型系统没有阻止下面这种原地修改：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">(</span>node<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  node<span class="token punctuation">.</span>id <span class="token operator">=</span> <span class="token string">&quot;changed&quot;</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> node<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种写法会破坏“不修改旧树”的假设，应坚持使用展开运算符创建新对象。</p><h2 id="_6-groupsiblingentries" tabindex="-1"><a class="header-anchor" href="#_6-groupsiblingentries"><span>6. <code>groupSiblingEntries</code></span></a></h2><p>它把同一父节点下至少两个文件/目录组合为：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  id<span class="token operator">:</span> <span class="token function">uid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  kind<span class="token operator">:</span> <span class="token string">&quot;one_of&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  minimumMatches<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  maximumMatches<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  alternatives<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>算法使用两个数组：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> entriesToGroup<span class="token operator">:</span> AnatomyEntry<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> remaining<span class="token operator">:</span> AnatomyNode<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>遍历一次 children：</p><ul><li>ID 被选中且是 file/directory → <code>entriesToGroup</code></li><li>其他节点 → <code>remaining</code></li></ul><p>最终：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> newChildren <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token operator">...</span>remaining<span class="token punctuation">,</span> group<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>因此需要注意：被分组的元素会从原位置移除，新的 <code>one_of</code> 会放在当前 children 的末尾。</p><hr><h1 id="三、validate-anatomy-for-publish-ts-验证定义是否合法" tabindex="-1"><a class="header-anchor" href="#三、validate-anatomy-for-publish-ts-验证定义是否合法"><span>三、<code>validate-anatomy-for-publish.ts</code>：验证定义是否合法</span></a></h1><p>文件：<a href="G:/Save/Grogramming/CodeForge/daedalus/packages/anatomies/src/core/validate-anatomy-for-publish.ts:1">validate-anatomy-for-publish.ts</a></p><p>它验证的是 Anatomy 定义本身，不读取真实文件。</p><p>返回值：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">Result<span class="token operator">&lt;</span>AnatomyDraftInput<span class="token punctuation">,</span> AnatomyValidationIssue<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>也就是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">Ok<span class="token operator">&lt;</span>AnatomyDraftInput<span class="token operator">&gt;</span></span>
<span class="line"><span class="token comment">// 定义可以继续发布/检查</span></span>
<span class="line"></span>
<span class="line">Err<span class="token operator">&lt;</span>AnatomyValidationIssue<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token comment">// 定义存在问题，而且一次返回所有问题</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_1-错误码类型写法" tabindex="-1"><a class="header-anchor" href="#_1-错误码类型写法"><span>1. 错误码类型写法</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> AnatomyValidationCode <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  duplicateId<span class="token operator">:</span> <span class="token string">&quot;duplicate_id&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> <span class="token class-name">Code</span> <span class="token operator">=</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token keyword">typeof</span> AnatomyValidationCode<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token keyword">keyof</span> <span class="token keyword">typeof</span> AnatomyValidationCode<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>拆开理解：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">keyof</span> <span class="token keyword">typeof</span> AnatomyValidationCode</span>
<span class="line"><span class="token comment">// &quot;duplicateId&quot; | &quot;duplicateLiteralName&quot; | ...</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">(</span><span class="token keyword">typeof</span> AnatomyValidationCode<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token comment">// &quot;duplicate_id&quot; | &quot;duplicate_literal_name&quot; | ...</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最终 Issue 的 <code>code</code> 只能是对象中的值，不会退化为普通 <code>string</code>。</p><h2 id="_2-路径和-placeholder-校验" tabindex="-1"><a class="header-anchor" href="#_2-路径和-placeholder-校验"><span>2. 路径和 placeholder 校验</span></a></h2><p>placeholder 正则：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^&lt;[^&lt;&gt;/\\\\]+&gt;[^/\\\\]*$</span><span class="token regex-delimiter">/</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>允许：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;Name&gt;</span>
<span class="line">&lt;Name&gt;.tsx</span>
<span class="line">&lt;Component&gt;.test.tsx</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>不允许：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">prefix-&lt;Name&gt;.tsx</span>
<span class="line">&lt;A/B&gt;.tsx</span>
<span class="line">&lt;&lt;Name&gt;&gt;.tsx</span>
<span class="line">&lt;Name&gt;/index.ts</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>真实路径检测会拒绝：</p><ul><li><code>/usr/src</code></li><li><code>C:\\src</code></li><li><code>\\\\server\\share</code></li><li><code>../src</code></li><li><code>src/../file</code></li></ul><p>它主要阻止绝对路径和目录穿越。不过普通的 <code>foo/bar</code> literal 不会被这个函数直接拒绝。</p><h2 id="_3-全局重复-id" tabindex="-1"><a class="header-anchor" href="#_3-全局重复-id"><span>3. 全局重复 ID</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> seenIds <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token operator">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>每访问一个节点：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>seenIds<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  issues<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">seenIds<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个 Set 在整个递归过程中共享，所以检查的是全树唯一性，而不是只检查兄弟节点。</p><h2 id="_4-同级-literal-重名" tabindex="-1"><a class="header-anchor" href="#_4-同级-literal-重名"><span>4. 同级 literal 重名</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> literalNames <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Map<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">string</span><span class="token operator">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Map 的结构是：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">Map<span class="token operator">&lt;</span>名称<span class="token punctuation">,</span> 第一次出现该名称的节点<span class="token constant">ID</span><span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>只检查同一 <code>nodes</code> 数组中的普通文件/目录：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>node<span class="token punctuation">.</span>kind <span class="token operator">===</span> <span class="token string">&quot;one_of&quot;</span> <span class="token operator">||</span> node<span class="token punctuation">.</span>name<span class="token punctuation">.</span>type <span class="token operator">!==</span> <span class="token string">&quot;literal&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">continue</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>进入 <code>one_of</code> 后，会递归对 alternatives 进行单独的同级检查。</p><p>因此“目录直属 children”和“某个 one_of 内部 alternatives”属于不同作用域。</p><h2 id="_5-one-of-范围" tabindex="-1"><a class="header-anchor" href="#_5-one-of-范围"><span>5. one-of 范围</span></a></h2><p>检查两类错误：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">minimumMatches <span class="token operator">&lt;</span> <span class="token number">1</span></span>
<span class="line">maximumMatches <span class="token operator">&lt;</span> <span class="token number">1</span></span>
<span class="line">minimumMatches <span class="token operator">&gt;</span> maximumMatches</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>以及：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">minimumMatches <span class="token operator">&gt;</span> alternatives<span class="token punctuation">.</span>length</span>
<span class="line">maximumMatches <span class="token operator">&gt;</span> alternatives<span class="token punctuation">.</span>length</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>例如有两个 alternatives，却配置：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">minimumMatches<span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">maximumMatches<span class="token operator">:</span> <span class="token number">3</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>最大匹配数 3 永远无法满足，所以是 <code>impossible_one_of</code>。</p><h2 id="_6-递归访问方式" tabindex="-1"><a class="header-anchor" href="#_6-递归访问方式"><span>6. 递归访问方式</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>node<span class="token punctuation">.</span>kind <span class="token operator">===</span> <span class="token string">&quot;one_of&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">visitNodes</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>alternatives<span class="token punctuation">,</span> node<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">continue</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token function">validateName</span><span class="token punctuation">(</span>node<span class="token punctuation">,</span> parentId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>node<span class="token punctuation">.</span>kind <span class="token operator">===</span> <span class="token string">&quot;directory&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">visitNodes</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>children<span class="token punctuation">,</span> node<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>continue</code> 很重要：它保证 <code>one_of</code> 不会继续进入普通 Entry 的名称和目录分支。</p><p>需要注意：这个函数做的是发布语义校验，并没有调用 <code>anatomyDraftInputSchema.safeParse()</code>。因此它假设调用方已经完成 Zod 解析。TypeScript 类型只在编译期有效，不能阻止外部 JSON 在运行时传入错误结构。</p><hr><h1 id="四、check-anatomy-ts-将定义与真实文件树对比" tabindex="-1"><a class="header-anchor" href="#四、check-anatomy-ts-将定义与真实文件树对比"><span>四、<code>check-anatomy.ts</code>：将定义与真实文件树对比</span></a></h1><p>文件：<a href="G:/Save/Grogramming/CodeForge/daedalus/packages/anatomies/src/core/check-anatomy.ts:1">check-anatomy.ts</a></p><p>输入分成两类：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">checkAnatomy</span><span class="token punctuation">(</span>definition<span class="token punctuation">,</span> entries<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>definition</code>：用户设计的 Anatomy 定义。</li><li><code>entries</code>：CLI 从真实文件系统收集出来的树。</li></ul><p>真实文件树刻意很简单：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">AnatomyFileTreeEntry</span> <span class="token operator">=</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span><span class="token punctuation">;</span> name<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">      kind<span class="token operator">:</span> <span class="token string">&quot;directory&quot;</span><span class="token punctuation">;</span></span>
<span class="line">      name<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">      children<span class="token operator">:</span> AnatomyFileTreeEntry<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>真实节点不需要：</p><ul><li>ID</li><li>quantity</li><li>policyOverrides</li><li>placeholder</li></ul><p>因为这些都是“预期约束”，不是真实文件属性。</p><h2 id="_1-首先验证定义" tabindex="-1"><a class="header-anchor" href="#_1-首先验证定义"><span>1. 首先验证定义</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> validated <span class="token operator">=</span> <span class="token function">validateAnatomyForPublish</span><span class="token punctuation">(</span>definition<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>validated<span class="token punctuation">.</span><span class="token function">isErr</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">err</span><span class="token punctuation">(</span>validated<span class="token punctuation">.</span>error<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>所以结果有两个层次：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">Err<span class="token operator">&lt;</span>AnatomyValidationIssue<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">&gt;</span></span>
<span class="line"><span class="token comment">// 规则定义本身不合法，无法检查</span></span>
<span class="line"></span>
<span class="line">Ok<span class="token operator">&lt;</span>AnatomyCheckResult<span class="token operator">&gt;</span></span>
<span class="line"><span class="token comment">// 检查完成，可能符合，也可能不符合</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>不要把 <code>Err</code> 和 <code>conforms: false</code> 混在一起：</p><ul><li><code>Err</code>：定义坏了。</li><li><code>Ok({ conforms: false })</code>：定义没问题，但真实项目违反了定义。</li></ul><h2 id="_2-名称匹配" tabindex="-1"><a class="header-anchor" href="#_2-名称匹配"><span>2. 名称匹配</span></a></h2><p>literal 会被转换为完整匹配正则：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">index<span class="token punctuation">.</span>ts → <span class="token operator">/</span><span class="token operator">^</span>index\\<span class="token punctuation">.</span>ts$<span class="token operator">/</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>特殊字符先通过：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">value<span class="token punctuation">.</span><span class="token function">replaceAll</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">[.*+?^\${}()|[\\]\\\\]</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token string">&quot;\\\\$&amp;&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>转义，防止文件名中的 <code>.</code>、<code>+</code> 等被当作正则语法。</p><p>placeholder：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token operator">&lt;</span>Name<span class="token operator">&gt;</span><span class="token punctuation">.</span>tsx → <span class="token operator">/</span><span class="token operator">^</span><span class="token punctuation">.</span><span class="token operator">+</span>\\<span class="token punctuation">.</span>tsx$<span class="token operator">/</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这里真正参与匹配的是 <code>&amp;gt;</code> 后面的 suffix。<code>&amp;lt;Name&amp;gt;</code> 只是给人看的变量名，并不限制实际文本内容。</p><h2 id="_3-数量转换" tabindex="-1"><a class="header-anchor" href="#_3-数量转换"><span>3. 数量转换</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">getQuantityRange</span><span class="token punctuation">(</span>entry<span class="token punctuation">.</span>quantity<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>将枚举转换成统一结构：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">{</span> minimum<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> maximum<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这样后续算法只需要比较：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">correctIndexes<span class="token punctuation">.</span>length <span class="token operator">&lt;</span> minimum</span>
<span class="line">position <span class="token operator">&gt;=</span> maximum</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>不必到处写 quantity 的 switch。</p><p>参数类型：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">AnatomyEntry<span class="token punctuation">[</span><span class="token string">&quot;quantity&quot;</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这是索引访问类型，表示直接复用 <code>AnatomyEntry</code> 中 <code>quantity</code> 字段的类型。</p><h2 id="_4-checknodes-与-consumed" tabindex="-1"><a class="header-anchor" href="#_4-checknodes-与-consumed"><span>4. <code>checkNodes</code> 与 <code>consumed</code></span></a></h2><p>每一层目录都会创建一个：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> consumed <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set<span class="token operator">&lt;</span><span class="token builtin">number</span><span class="token operator">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Set 中存的是已经被某条约束匹配/处理的真实文件下标。</p><p>这样一个真实文件不会在正常情况下被重复用于多个预期 Entry，同时最后可以把未消费节点报告为 <code>unexpected_entry</code>。</p><p>单个 Entry 的匹配顺序是：</p><ol><li>名称相同但 kind 不同 → <code>nesting_mismatch</code></li><li>kind 相同、名称只存在大小写差异 → <code>name_mismatch</code></li><li>名称和 kind 都正确 → 数量检查</li><li>正确目录 → 递归检查 children</li><li>没有关联匹配且不足最小数量 → <code>missing_required</code></li><li>所有约束处理后仍未消费 → <code>unexpected_entry</code></li></ol><p>例如预期：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">file index.ts</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>实际：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">directory index.ts/</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>它会报告 <code>nesting_mismatch</code>，不会再同时报告一条 <code>missing_required</code>，因为代码专门避免了重复报错：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">nestingMismatchIndexes<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span></span>
<span class="line">nameMismatchIndexes<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-策略继承" tabindex="-1"><a class="header-anchor" href="#_5-策略继承"><span>5. 策略继承</span></a></h2><p>策略优先级在 <a href="G:/Save/Grogramming/CodeForge/daedalus/packages/schemas/src/anatomy-schema.ts:256">resolveAnatomyPolicies</a> 中实现：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">当前 Entry 的 policyOverrides</span>
<span class="line">            ↓ 没配置</span>
<span class="line">最近的父目录 policyOverrides</span>
<span class="line">            ↓ 没配置</span>
<span class="line">Anatomy defaultPolicies</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ancestors</code> 是从根到当前目录的数组，解析时反转后寻找，因此最近的父目录优先。</p><p>需要注意：</p><ul><li><code>one_of</code> 本身没有 <code>policyOverrides</code>，它的匹配错误使用父目录或全局策略。</li><li><code>quantityExceeded</code> 使用 <code>unexpectedEntry</code> 策略，因为策略模型中没有单独的 quantity 策略。</li></ul><h2 id="_6-one-of-检查" tabindex="-1"><a class="header-anchor" href="#_6-one-of-检查"><span>6. one-of 检查</span></a></h2><p>对于：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  minimumMatches<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  maximumMatches<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  alternatives<span class="token operator">:</span> <span class="token punctuation">[</span>index<span class="token punctuation">.</span>ts<span class="token punctuation">,</span> index<span class="token punctuation">.</span>tsx<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>实际情况：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">只有 index.ts       → 匹配数 1，通过</span>
<span class="line">两个都没有          → 匹配数 0，one_of_mismatch</span>
<span class="line">两个文件都存在      → 匹配数 2，one_of_mismatch</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>匹配数表示“有多少个 alternative 得到匹配”，不是文件总数。</p><p>这里采用按定义顺序、贪心消费的算法。若多个 placeholder 可以匹配同一个真实文件，定义顺序可能影响最终结果；设计 Anatomy 时应尽量避免重叠模式，例如同时存在：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;Name&gt;.tsx</span>
<span class="line">&lt;Component&gt;.tsx</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>因为两者实际正则完全相同。</p><h2 id="_7-汇总和-conforms" tabindex="-1"><a class="header-anchor" href="#_7-汇总和-conforms"><span>7. 汇总和 conforms</span></a></h2><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> summary <span class="token operator">=</span> issues<span class="token punctuation">.</span><span class="token function">reduce</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span>counts<span class="token punctuation">,</span> issue<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token operator">...</span>counts<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span>issue<span class="token punctuation">.</span>severity<span class="token punctuation">]</span><span class="token operator">:</span> counts<span class="token punctuation">[</span>issue<span class="token punctuation">.</span>severity<span class="token punctuation">]</span> <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> block<span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> warn<span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> allow<span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>即使 severity 是 <code>&quot;allow&quot;</code>，Issue 仍会保留，只是不阻止通过。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">conforms<span class="token operator">:</span> summary<span class="token punctuation">.</span>block <span class="token operator">===</span> <span class="token number">0</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>因此：</p><ul><li>有 warn：仍然 <code>conforms: true</code></li><li>有 allow：仍然 <code>conforms: true</code></li><li>至少一个 block：<code>conforms: false</code></li></ul><hr><h1 id="五、贯穿三个文件的例子" tabindex="-1"><a class="header-anchor" href="#五、贯穿三个文件的例子"><span>五、贯穿三个文件的例子</span></a></h1><p>先用树操作创建两个文件：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">let</span> structure <span class="token operator">=</span> <span class="token function">createEmptyStructure</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">structure <span class="token operator">=</span> <span class="token function">insertAnatomyNode</span><span class="token punctuation">(</span></span>
<span class="line">  structure<span class="token punctuation">,</span></span>
<span class="line">  <span class="token keyword">null</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function">createFileEntry</span><span class="token punctuation">(</span><span class="token string">&quot;index.ts&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;exactly_one&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">structure <span class="token operator">=</span> <span class="token function">insertAnatomyNode</span><span class="token punctuation">(</span></span>
<span class="line">  structure<span class="token punctuation">,</span></span>
<span class="line">  <span class="token keyword">null</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function">createFileEntry</span><span class="token punctuation">(</span><span class="token string">&quot;index.tsx&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;exactly_one&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后把它们组合为 one-of：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line">structure <span class="token operator">=</span> <span class="token function">groupSiblingEntries</span><span class="token punctuation">(</span></span>
<span class="line">  structure<span class="token punctuation">,</span></span>
<span class="line">  <span class="token keyword">null</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span>indexTsId<span class="token punctuation">,</span> indexTsxId<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果类似：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  schemaVersion<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">  root<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    children<span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        id<span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        kind<span class="token operator">:</span> <span class="token string">&quot;one_of&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        minimumMatches<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">        maximumMatches<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">        alternatives<span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">          <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token punctuation">{</span> type<span class="token operator">:</span> <span class="token string">&quot;literal&quot;</span><span class="token punctuation">,</span> value<span class="token operator">:</span> <span class="token string">&quot;index.ts&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token punctuation">{</span> type<span class="token operator">:</span> <span class="token string">&quot;literal&quot;</span><span class="token punctuation">,</span> value<span class="token operator">:</span> <span class="token string">&quot;index.tsx&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>发布时 <code>validateAnatomyForPublish</code> 检查：</p><ul><li>所有 ID 是否唯一。</li><li>alternative 名称是否重复。</li><li><code>1..1</code> 是否是合法范围。</li><li>范围是否没有超过两个 alternatives。</li></ul><p>CLI 检查真实目录：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">[</span></span>
<span class="line">  <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token string">&quot;index.ts&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&quot;file&quot;</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token string">&quot;index.tsx&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两个 alternatives 都匹配，匹配数量为 2，但最大允许 1，最终产生：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  code<span class="token operator">:</span> <span class="token string">&quot;one_of_mismatch&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  severity<span class="token operator">:</span> <span class="token string">&quot;warn&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;block&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;allow&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  constraintId<span class="token operator">:</span> oneOfGroupId<span class="token punctuation">,</span></span>
<span class="line">  path<span class="token operator">:</span> <span class="token string">&quot;.&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="最需要记住的-typescript-点" tabindex="-1"><a class="header-anchor" href="#最需要记住的-typescript-点"><span>最需要记住的 TypeScript 点</span></a></h2><ul><li><code>kind</code> / <code>type</code> 是判别字段，优先通过判断它们缩窄联合类型。</li><li><code>(typeof Values)[number]</code> 从常量数组生成值联合类型。</li><li><code>(typeof Codes)[keyof typeof Codes]</code> 从常量对象生成值联合类型。</li><li><code>AnatomyEntry[&quot;quantity&quot;]</code> 复用对象字段类型。</li><li><code>Extract&amp;lt;Union, Condition&amp;gt;</code> 从联合类型中提取某个分支。</li><li><code>Result&amp;lt;T, E&amp;gt;</code> 明确区分成功值和错误值。</li><li><code>as T</code>、<code>as AnatomyEntry</code> 不提供运行时安全，只是开发者向 TS 作保证。</li><li>Zod 的 <code>.uuid()</code>、<code>.min(2)</code> 等运行时约束不会完整体现在普通 TS 类型中。</li><li>不可变更新函数要求 updater 保持纯函数习惯，类型本身没有强制 <code>readonly</code>。</li></ul><p>当前核心测试共 20 项全部通过，<code>tsc --noEmit</code> 也通过；本次仅做了代码分析，没有修改文件。</p>`,233)])])}const o=s(t,[["render",l]]),r=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E9%A1%B9%E7%9B%AE%E7%AC%94%E8%AE%B0/%E4%BB%A3%E8%BE%BE%E7%BD%97%E6%96%AF/Anatomy/core/core.html","title":"二、anatomy-tree.ts：树的构造、查询和修改","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/项目笔记/代达罗斯/Anatomy/core/core.md"}');export{o as comp,r as data};
